// Native renderer regression for approved question UX. Isolated synthetic profile;
// answers terminate at a controlled IPC endpoint: no model, key or Git request.
const { _electron: electron } = require('playwright');
const fs = require('node:fs/promises');
const path = require('node:path');
const os = require('node:os');
const assert = require('node:assert/strict');
const helpers = require('./ui-test-helpers.cjs');
(async () => {
  const output = process.env.AURA_FEEDBACK_OUTPUT || path.join(os.homedir(), 'Library/Application Support/Aura1/ReleaseReports/feedback-20261026/questions-after');
  await fs.mkdir(output, { recursive:true });
  const root = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'aura-feedback-questions-'))), project = path.join(root, 'QuestionTest');
  await fs.mkdir(path.join(project, 'public'), { recursive:true });
  await fs.writeFile(path.join(project, 'public/index.html'), '<!doctype html><html lang="da"><title>Syntetisk prøve</title><h1>Syntetisk prøve</h1></html>');
  let app, page; const checks = [], errors = [];
  const pass = (name, detail) => { checks.push({name, detail}); console.log('PASS ' + name); };
  try {
    app = await electron.launch({executablePath:require('electron'),args:[path.join(__dirname,'..'),'--user-data-dir='+path.join(root,'appdata')],env:{...process.env,ELECTRON_RUN_AS_NODE:undefined}});
    page = await app.firstWindow(); page.on('pageerror', e=>errors.push(e.message));
    await app.evaluate(({app,session,ipcMain}, root) => {
      app.setPath('documents',root);
      session.defaultSession.webRequest.onBeforeRequest((details, callback)=>callback({cancel:/^https?:/.test(details.url)}));
      global.fetch=async()=>{throw Error('Question regression forbids external requests.');};
      global.feedbackAnswers=[]; global.feedbackReplyFailure=false;
      ipcMain.removeHandler('agent:question');
      ipcMain.handle('agent:question', async(_event,value)=>{
        global.feedbackAnswers.push(value);
        await new Promise(resolve=>setTimeout(resolve,120));
        return global.feedbackReplyFailure ? {ok:false,error:'Syntetisk svarfejl'} : {ok:true,value:null};
      });
    },root);
    await helpers.forbidGitWrites(app); await helpers.skipIntroduction(page); await helpers.openExistingProject(app,page,project);
    await app.evaluate(({BrowserWindow})=>BrowserWindow.getAllWindows().find(w=>w.webContents.getURL().startsWith('harness://')).setContentSize(1440,900));
    const owner=await page.evaluate(()=>selectedOwner());
    const emit=event=>app.evaluate(({BrowserWindow},data)=>BrowserWindow.getAllWindows().find(w=>w.webContents.getURL().startsWith('harness://')).webContents.send('harness:event',{...data.event,...data.owner}),{event,owner});
    const card=()=>page.locator('.question-card');
    const answers=()=>app.evaluate(()=>global.feedbackAnswers);
    const reset=async()=>app.evaluate(()=>{global.feedbackAnswers=[];global.feedbackReplyFailure=false;});
    const ask=async(id, questions)=>{await reset();await emit({type:'question.asked',properties:{id,questions}});await card().waitFor();};
    const base={question:'Hvem skal kunne tilmelde sig?',header:'Brugere',options:[{label:'Alle borgere (anbefalet)',description:'Uden login'},{label:'Inviterede',description:'Med invitation'}],custom:true};
    await ask('free-answer',[base]);
    assert.equal(await card().locator('textarea').count(),1,'Free answer must be visible without an extra click.');
    assert.equal(await card().locator('.answer-choice').count(),2); assert.equal((await answers()).length,0);
    assert.equal(await page.evaluate(()=>viewFor().waitingFor.length),1); pass('Frit svar er synligt; forslag og ubesvaret tilstand bevares');
    await card().locator('textarea').fill('Alle'); await card().locator('textarea').press('Shift+Enter');
    assert.equal(await card().locator('textarea').inputValue(),'Alle\n'); assert.equal((await answers()).length,0); pass('Shift+Enter giver ny linje uden svar');
    await card().locator('textarea').fill('Alle borgere, højst to pladser.');
    await page.screenshot({path:path.join(output,'01-question-dark-1440x900.png')});
    await card().locator('textarea').evaluate(el=>{el.dispatchEvent(new CompositionEvent('compositionstart',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));});
    assert.equal((await answers()).length,0);
    await card().locator('textarea').evaluate(el=>{el.dispatchEvent(new CompositionEvent('compositionend',{bubbles:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',isComposing:true,bubbles:true,cancelable:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:229,bubbles:true,cancelable:true}));});
    assert.equal((await answers()).length,0); pass('IME composition, isComposing og tast 229 sender ikke');
    await card().locator('textarea').press('Enter');
    await card().waitFor({state:'detached'}); assert.deepEqual((await answers())[0].answers,[['Alle borgere, højst to pladser.']]);
    assert.equal(await page.evaluate(()=>viewFor().waitingFor.length),0); pass('Enter sender det præcise svar og rydder ventetilstanden efter kvittering');
    await ask('empty',[base]); await card().locator('textarea').fill('   '); await card().locator('textarea').press('Enter'); assert.equal((await answers()).length,0); assert.equal(await card().count(),1); pass('Tomt/blankt svar sendes ikke');
    await card().locator('.answer-choice').first().click(); await card().waitFor({state:'detached'}); assert.deepEqual((await answers())[0].answers,[['Alle borgere (anbefalet)']]); pass('Ét valgsvar kan stadig sendes direkte');
    const many={...base,multiple:true,options:['A','B','C','D','E'].map(label=>({label,description:label}))};
    await ask('sequence',[many,{...base,question:'Hvor?',custom:false}]);
    await card().locator('textarea').fill('Min kladde'); await card().locator('.answer-choice').filter({hasText:'A'}).click();
    assert.equal(await card().locator('textarea').inputValue(),'Min kladde'); await card().getByRole('button',{name:'Vis 1 svar mere'}).click(); assert.equal(await card().locator('textarea').inputValue(),'Min kladde');
    await card().locator('.answer-choice').filter({hasText:'E'}).click(); await card().getByRole('button',{name:'Fortsæt med 2 svar',exact:true}).click();
    assert.equal(await card().locator('textarea').count(),0); assert.equal((await answers()).length,0);
    await card().getByRole('button',{name:'Tilbage',exact:true}).click(); assert.equal(await card().locator('textarea').inputValue(),'Min kladde'); assert.equal(await card().locator('[aria-pressed="true"]').count(),1);
    await card().getByRole('button',{name:'Fortsæt med 2 svar',exact:true}).click(); await card().locator('.answer-choice').last().click(); await card().waitFor({state:'detached'});
    assert.deepEqual((await answers())[0].answers,[['A','E'],['Inviterede']]); pass('Flervalg, flere muligheder, tilbage, kladde og sekventielle svar bevares; custom:false respekteres');
    await ask('skip',[base]); await card().getByRole('button',{name:'Spring over',exact:true}).click(); await card().waitFor({state:'detached'}); assert.equal((await answers())[0].skip,true); pass('Spring over bruger den eksisterende eksplicitte skip-handling');
    await ask('failed',[base]); await app.evaluate(()=>{global.feedbackReplyFailure=true;}); await card().locator('textarea').fill('Gem dette svar'); await card().locator('textarea').press('Enter');
    await page.waitForFunction(()=>document.querySelector('#message').textContent==='Syntetisk svarfejl'); assert.equal(await card().locator('textarea').inputValue(),'Gem dette svar'); assert.equal(await card().locator('textarea').isEnabled(),true); assert.equal(await page.evaluate(()=>viewFor().waitingFor.length),1); pass('Afvist IPC-svar bevarer spørgsmål, kladde og ventetilstand');
    await reset(); await card().locator('textarea').evaluate(el=>{el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));el.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true}));});
    await card().waitFor({state:'detached'}); assert.equal((await answers()).length,1); pass('To hurtige Enter udløser kun ét afventende svar');
    await ask('cancelled',[base]); await emit({type:'question.rejected',properties:{requestID:'cancelled'}}); await card().waitFor({state:'detached'}); assert.equal((await answers()).length,0); pass('Afvist spørgsmål fjernes uden automatisk svar');
    const plan={id:'feedback-plan',source:'ai',at:Date.now(),text:'## Det bygger vi\nEn mødeoversigt med tilmelding.\n\n## Sådan skal det se ud\nRolige grønne flader og tydelig navigation.\n\n## Teknik og data\nHTML og lokale eksempeldata. Kommandoen npm run dev er en teknisk detalje.\n\n## Det skal du prøve\n- Vælg et møde og tilmeld dig.\n- Kontrollér bekræftelsen.'};
    await emit({type:'plan.ready',plan}); await page.locator('#plan-card').waitFor();
    assert.equal(await page.locator('#plan-card h3').innerText(),'Kort byggeplan');
    const planItems=await page.locator('#plan-summary li').allTextContents(); assert.equal(planItems.length,3);
    assert.match(planItems[0],/En mødeoversigt med tilmelding/); assert.match(planItems[1],/Rolige grønne flader/); assert.match(planItems[2],/Vælg et møde/); assert.ok(!planItems.join('').includes('npm run dev'));
    assert.match(await page.locator('#plan-text .plan-teknik summary').textContent(),/Teknik og data/);
    assert.match(await page.locator('#plan-text .plan-teknik').textContent(),/npm run dev/);
    await page.locator('#plan-card').scrollIntoViewIfNeeded(); await page.screenshot({path:path.join(output,'02-short-plan-dark-1440x900.png')});
    assert.equal(await page.evaluate(()=>activePlan.id),'feedback-plan'); pass('Kort byggeplan bruger tre faktiske planafsnit; teknik og hele den samme plan bevares');
    await emit({type:'plan.ready',plan:{...plan,id:'feedback-free-plan',text:'En fri plan uden standardoverskrifter.'}});
    await page.waitForFunction(()=>document.querySelector('#plan-summary').textContent==='En fri plan uden standardoverskrifter.'); assert.equal(await page.locator('#plan-summary li').count(),1); pass('Fri plan bevarer sit resumé uden opfundne afsnit');
    await helpers.assertNoGitWrites(app); assert.deepEqual(errors,[]);
    await fs.writeFile(path.join(output,'report.json'),JSON.stringify({platform:process.platform,profile:root,checks,errors,scope:'Actual Electron renderer with synthetic questions and controlled answer IPC. No real AI, credentials, Windows or release.'},null,2)+'\n');
    console.log(JSON.stringify({output,passed:checks.length}));
  } catch(error) { if(page)await page.screenshot({path:path.join(output,'failure.png')}).catch(()=>{}); await fs.writeFile(path.join(output,'error.json'),JSON.stringify({error:error.message,checks,errors,profile:root},null,2)); throw error; }
  finally {await app?.close();}
})().catch(error=>{console.error(error);process.exitCode=1;});
